#!/usr/bin/env python3
"""Run the real-model smoke corpus generated by make-chinese-fixtures.swift."""
from pathlib import Path
import json, os, subprocess

root = Path(__file__).resolve().parents[1]
cli = root / '.build/release/digup'
fixtures = root / '.dev/fixtures'
index = root / '.dev/verified-index'
report = root / '.dev/verification'
report.mkdir(parents=True, exist_ok=True)
env = dict(os.environ, DIGUP_MODELS=str(root / '.dev/models'))
indexed = subprocess.run([str(cli), 'index', str(fixtures), '--index', str(index)],
                         env=env, text=True, capture_output=True, check=True)
(report / 'index.log').write_text(indexed.stdout + indexed.stderr)
cases = [
    ('宠物', '租房合同.pdf', 2),
    ('zufanghetong', '租房合同.pdf', None),
    ('zfht', '租房合同.pdf', None),
    ('PAY-20261024', '付款失败截图.png', None),
    ('银行卡余额', '付款失败截图.png', None),
    ('可以带猫入住的合同', '租房合同.pdf', 2),
    ('月底需要什么报销材料', '财务预算.md', None),
    ('做茄子的方法', '家常菜谱.txt', None),
]
results = []
for query, filename, page in cases:
    run = subprocess.run([str(cli), 'search', query, '--index', str(index), '--json'],
                         env=env, text=True, capture_output=True, check=True)
    hits = json.loads(run.stdout)
    first = hits[0] if hits else {}
    passed = Path(first.get('path', '')).name == filename and (page is None or first.get('loc') == page)
    results.append(dict(query=query, expected=filename, expected_page=page, passed=passed, hits=hits))
    print(('PASS' if passed else 'FAIL') + '  ' + query + ' → ' + Path(first.get('path', '')).name, flush=True)
(report / 'queries.json').write_text(json.dumps(results, ensure_ascii=False, indent=2))
assert all(item['passed'] for item in results), 'Search smoke check failed; see .dev/verification/queries.json'
print(f'{len(results)}/{len(results)} smoke queries passed. Small synthetic corpus only; not a broad quality benchmark.')
